input.content:
'use server'

import { revalidatePath } from 'next/cache'

const preferences = new Map<string, boolean>()

export async function getNotificationPreference(userId: string): Promise<boolean> {
  return preferences.get(userId) ?? false
}

export async function toggleNotificationPreference(userId: string): Promise<void> {
  const current = preferences.get(userId) ?? false
  preferences.set(userId, !current)
  revalidatePath('/')
}

import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  const userId = 'demo-user'
  const isEnabled = await getNotificationPreference(userId)

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference.bind(null, userId)}>
        <button type="submit">
          Notifications: {isEnabled ? 'On' : 'Off'}
        </button>
      </form>
    </main>
  )
}
